window.FIXTURES=window.FIXTURES||{};window.FIXTURES["speech"]={"vid":"mktMnyUq8t0","speaker":"Luiz Inácio Lula da Silva","role":"President","country":"Brazil","region":"Latin America & Caribbean","url":"https://www.youtube.com/watch?v=mktMnyUq8t0","date":"20260922","title":"🇧🇷 Brazil - President Addresses United Nations General Debate, 81st Session | #UNGA","seconds":1271,"words":2408,"counts":{"claims":44,"promises":12,"attacks":15},"topics":[{"topic":"UN reform","share":0.1531,"seconds":195},{"topic":"Climate change","share":0.1009,"seconds":128},{"topic":"Brazil hunger","share":0.0552,"seconds":70},{"topic":"Brazil deforestation","share":0.0523,"seconds":66},{"topic":"Brazil elections","share":0.0515,"seconds":65},{"topic":"International Court of Justice","share":0.0509,"seconds":65},{"topic":"Global development","share":0.0508,"seconds":65},{"topic":"Israel-Palestine conflict","share":0.0499,"seconds":63},{"topic":"Brazil economy","share":0.0498,"seconds":63},{"topic":"Brazil organized crime","share":0.0498,"seconds":63},{"topic":"Latin America diplomacy","share":0.0492,"seconds":63},{"topic":"Women's rights","share":0.0488,"seconds":62},{"topic":"Brazil digital policy","share":0.0486,"seconds":62},{"topic":"Transnational organized crime","share":0.0484,"seconds":62},{"topic":"AI regulation","share":0.0481,"seconds":61},{"topic":"Venezuela elections","share":0.0479,"seconds":61},{"topic":"Brazil democracy","share":0.0449,"seconds":57}],"timeline":[[2,73,null],[73,141,"UN reform"],[142,206,"UN reform"],[207,277,"Brazil hunger"],[278,341,"Israel-Palestine conflict"],[342,407,"International Court of Justice"],[408,471,"Latin America diplomacy"],[472,533,"Venezuela elections"],[534,595,"Transnational organized crime"],[597,660,"Brazil organized crime"],[661,728,"Climate change"],[730,791,"Climate change"],[792,859,"Brazil deforestation"],[860,921,"AI regulation"],[923,985,"Brazil digital policy"],[986,1051,"Global development"],[1052,1115,"Brazil economy"],[1116,1178,"Women's rights"],[1180,1243,"UN reform"],[1244,1310,"Brazil elections"],[1311,1368,"Brazil democracy"]],"stances":{"UN reform":"Lula da Silva states that the UN's credibility is at its lowest point and its ability to protect vulnerable populations is weak due to Security Council inaction.","Brazil hunger":"Lula da Silva states that he removed Brazil from the hunger map as a result of his presidency.","Israel-Palestine conflict":"Lula da Silva asserts that the Netanyahu government perpetrated a genocide against women and children in Gaza, causing lasting trauma for Palestinian generations.","International Court of Justice":"Lula argues that persecuting the International Criminal Court encourages crimes to go unpunished and calls for the protection of UN special reporter Francesca Albanese.","Latin America diplomacy":"Lula da Silva argues that diplomacy is the only viable option for conflict resolution and emphasizes the need for regional integration free from ideological differences.","Venezuela elections":"Lula states that Nicaragua's approach to its problems by preventing opposition participation is incorrect, implying a similar stance on Venezuela where the people should define their own destiny.","Transnational organized crime":"Lula da Silva states that Brazil is ready to confront criminal organizations and will not outsource border defense, emphasizing the need for international cooperation to stop the flow of weapons and money rather than relying on military assets like aircraft carriers.","Brazil organized crime":"Lula da Silva states that Brazil has established an international police cooperation center, conducted its largest operation against organized crime in 2025, and passed legislation imposing heavier sentences for organized crime than for terrorism while committing to a relentless fight against corruption.","Climate change":"Lula da Silva states that climate change has been removed from major international agendas and calls for a renewed offensive to address it.","Brazil deforestation":"Lula da Silva states that Brazil is committed to reducing deforestation, which has already been cut in half and reached its lowest level in 11 years.","AI regulation":"Lula da Silva argues that regulating big tech and artificial intelligence is essential to prevent ethical violations, digital ultra-liberalism, and the exploitation of addiction for profit.","Brazil digital policy":"Lula da Silva asserts that Brazil has enacted advanced legislation to protect vulnerable groups online, will ensure fair compensation for creators, and refuses to privatize the PIX payment system despite multinational pressure.","Global development":"Lula argues that global change should focus on cutting privileges to fund public services and solidarity rather than reviving supremacy or subjugation.","Brazil economy":"Lula da Silva states that Brazil has adopted an economic model focused on income distribution and job creation, resulting in sustainable growth and record exports despite high tariffs.","Women's rights":"Lula da Silva asserts that Brazil is building a society where women have full access to power and the job market without needing permission, and calls for a global effort to end femicide and violence against women.","Brazil elections":"Lula da Silva states that the upcoming Brazilian election will be a decisive choice between democracy and denialism, emphasizing the need for competitive and transparent processes while warning against misinformation and foreign interference.","Brazil democracy":"Lula da Silva asserts that Brazil has a robust election system and will not allow enemies of democracy to undermine the popular will."},"claims":[{"t":75,"quote":"this is the 10th time I have opened the general debate of this assembly","topic":"UN reform","kind":"number"},{"t":107,"quote":"Its credibility has never been lower. Its ability to protect the most vulnerable, those who have no army or arsenals, has never been so weak.","topic":"UN reform","kind":"fact"},{"t":129,"quote":"In 1946, at the first session of this assembly, Brazil warned of the high price that the international community would pay for the right to veto.","topic":"UN reform","kind":"fact"},{"t":159,"quote":"The year of 2025 record, the highest number of armed conflict since the World War II.","topic":"UN reform","kind":"number"},{"t":168,"quote":"Trillions of dollars are funding a new arms race.","topic":"UN reform","kind":"number"},{"t":250,"quote":"This general assembly recently corrected a historical distortion in the world map. It recognized the trafficking of enslaved Africans as the gravest crime against","topic":"Brazil hunger","kind":"fact"},{"t":320,"quote":"Generations of Palestinians will carry the pain and trauma left by the genocide of women and children perpetrated by Netanyahu government in Gaza.","topic":"Israel-Palestine conflict","kind":"fact"},{"t":336,"quote":"Israeli civilians paid the price for radicalism and intolerance of Hamas terrorist acts.","topic":"Israel-Palestine conflict","kind":"fact"},{"t":397,"quote":"The war between Russia and Ukraine has dragged on for five years in a humanitarian drama that continues to claim lives.","topic":"International Court of Justice","kind":"fact"},{"t":417,"quote":"Initiatives such as the friends of peace group created by Brazil and China reveal that there are forces in the international community willing to work towards dialogue.","topic":"Latin America diplomacy","kind":"fact"},{"t":467,"quote":"The countries in the region have experienced the horrors of authoritarian regimes.","topic":"Latin America diplomacy","kind":"fact"},{"t":497,"quote":"The Venezuelan people deserve to define their own destiny.","topic":"Venezuela elections","kind":"fact"},{"t":501,"quote":"Nicaragua will not solve its problems by preventing the opposition from running in the elections.","topic":"Venezuela elections","kind":"fact"},{"t":514,"quote":"In Cuba, the world watches in horror as collective punishment is imposed on 10 million people by an illegal economic and energy","topic":"Venezuela elections","kind":"number"},{"t":540,"quote":"Workers are har are robbed. Mothers lose their children. Police officers do not make it back home.","topic":"Transnational organized crime","kind":"fact"},{"t":572,"quote":"That's the spirited of the proposal that I personally handed to the US president.","topic":"Transnational organized crime","kind":"self_credit"},{"t":597,"quote":"In Manal, the city of the Amazon state, we created the Amazon International Police Cooperation Center, bringing together public safety authorities from nine Amazon region countries.","topic":"Brazil organized crime","kind":"fact"},{"t":609,"quote":"In 2025, we carried out the biggest operation against organized crime in Brazil's history.","topic":"Brazil organized crime","kind":"number"},{"t":616,"quote":"We broke records of drug seizures as well as unlawful assets and resources.","topic":"Brazil organized crime","kind":"fact"},{"t":628,"quote":"The anti-faction bill that we just have passed establish heavier sentences for organized crime than those carried by terrorism.","topic":"Brazil organized crime","kind":"fact"},{"t":677,"quote":"We will never forget the millions of lives lost due to the negligence in the fight against COVID 19.","topic":"Climate change","kind":"fact"},{"t":704,"quote":"This year, however, the topic disappeared from the debates of the G7 and G20 forums that bring together the largest carbon emitters.","topic":"Climate change","kind":"fact"},{"t":730,"quote":"The glaciers in the Himalayas are melting. The super aeronneo may cause torrential rains, droughts, and forest fires in different parts of the globe.","topic":"Climate change","kind":"fact"},{"t":754,"quote":"Brazil has been demonstrating that it is possible to combine economic growth with reduced emissions.","topic":"Climate change","kind":"self_credit"},{"t":762,"quote":"We have achieved our self-sufficiency in oil and will continue to explore the potential of new reserves such as those in the equatorial margin.","topic":"Climate change","kind":"fact"},{"t":797,"quote":"We will continue to reduce deforestation which has been cut in half in the Amazon and reaching its lowest level in 11 years.","topic":"Brazil deforestation","kind":"number"},{"t":815,"quote":"Brazil is a global reference in green energy.","topic":"Brazil deforestation","kind":"fact"},{"t":910,"quote":"The billiond dollar bedding industry turns addiction into profit.","topic":"AI regulation","kind":"fact"},{"t":916,"quote":"Its exponential dissemination is increasing debt levels and destroying homes.","topic":"AI regulation","kind":"fact"},{"t":929,"quote":"We passed one of the most advanced pieces of legislations in the world to protect children, adolescents, and women in the digital environment.","topic":"Brazil digital policy","kind":"fact"},{"t":953,"quote":"a free public payment infrastructure that has made financial inclusion a reality for millions of Brazilians.","topic":"Brazil digital policy","kind":"fact"},{"t":1034,"quote":"Initiatives such as the global alliance against hunger and poverty launched by Brazil and the UN intergovernmental panel on inequality launched by South Africa steamed from this political will.","topic":"Global development","kind":"fact"},{"t":1052,"quote":"We have adopted an economic model based on income distribution, job creation and wage increases.","topic":"Brazil economy","kind":"fact"},{"t":1069,"quote":"Brazil has returned to sustainable growth.","topic":"Brazil economy","kind":"fact"},{"t":1073,"quote":"We are the third largest destination of for foreign direct investment.","topic":"Brazil economy","kind":"number"},{"t":1078,"quote":"Despite the high tariffs imposed against our economy, this year we shall break a new record in our exports.","topic":"Brazil economy","kind":"fact"},{"t":1132,"quote":"We are building a Brazil where women don't need permission to occupy positions of power or enter the job market.","topic":"Women's rights","kind":"fact"},{"t":1143,"quote":"A country free from femicide where no woman inside or outside their home lives under the threat of violence.","topic":"Women's rights","kind":"fact"},{"t":1184,"quote":"Over eight decades, it has contributed to the decolonization, promoted human rights, and supported sustainable development.","topic":"UN reform","kind":"fact"},{"t":1194,"quote":"It has protected migrants and refugees, condemned racism, anti-semitism, and religious intolerance.","topic":"UN reform","kind":"fact"},{"t":1251,"quote":"On October the 4th, millions of Brazilians will go to the polls to define their destiny.","topic":"Brazil elections","kind":"fact"},{"t":1259,"quote":"They're not just voting for president of the republic, state governors, and representatives of the legislative branch.","topic":"Brazil elections","kind":"fact"},{"t":1311,"quote":"But we have a modern and robust election system under the watchful eye of a pluralistic citizenry and a free press.","topic":"Brazil democracy","kind":"fact"},{"t":1334,"quote":"Brazil continues to be a sovereign country.","topic":"Brazil democracy","kind":"fact"}],"promises":[{"t":550,"quote":"But we will not we will not outsource the responsibility of defending its borders and guaranteeing our population the right to live without fear.","topic":"Transnational organized crime","kind":"promise"},{"t":642,"quote":"The fight against corruption shall remain relentless no matter who it hurts.","topic":"Brazil organized crime","kind":"promise"},{"t":772,"quote":"But we will not abandon the environmental agenda.","topic":"Climate change","kind":"promise"},{"t":775,"quote":"We will move forward with a road map for the decarbonization of the Brazilian economy.","topic":"Climate change","kind":"promise"},{"t":797,"quote":"We will continue to reduce deforestation which has been cut in half in the Amazon and reaching its lowest level in 11 years.","topic":"Brazil deforestation","kind":"promise"},{"t":836,"quote":"Access to our minerals will be contingent upon mandatory value generation in our territory, technology transfer and the supply of strategic national sectors.","topic":"Brazil deforestation","kind":"promise"},{"t":939,"quote":"We will ensure fair compensation for artists, musicians, and other visual content creators.","topic":"Brazil digital policy","kind":"promise"},{"t":947,"quote":"We will not give in to pressure from multinationals that want to privatize our PIX","topic":"Brazil digital policy","kind":"threat"},{"t":1082,"quote":"this year we shall break a new record in our exports.","topic":"Brazil economy","kind":"promise"},{"t":1107,"quote":"Achieving this goal requires ending the so-called six* one working schedule to guarantee workers two days off per week.","topic":"Brazil economy","kind":"promise"},{"t":1322,"quote":"We will not allow the enemies of democracy, whether domestic or foreign, to undermine popular will.","topic":"Brazil democracy","kind":"promise"},{"t":1338,"quote":"Nobody, nobody will turn us away from this path.","topic":"Brazil democracy","kind":"promise"}],"attacks":[{"t":120,"quote":"We are all held hostage by the inaction of the security council for failing to fulfill its role.","topic":"UN reform","target":"United Nations Security Council"},{"t":326,"quote":"genocide of women and children perpetrated by Netanyahu government in Gaza","topic":"Israel-Palestine conflict","target":"Israel"},{"t":338,"quote":"radicalism and intolerance of Hamas terrorist acts","topic":"Israel-Palestine conflict","target":"Hamas"},{"t":342,"quote":"Persecuting the International Criminal Court and its members encourages these crimes to go unpunished.","topic":"International Court of Justice","target":"ICC opponents"},{"t":373,"quote":"Threatening civilizations with extinction will not bring stability to the Middle East.","topic":"International Court of Justice","target":"Existential threats"},{"t":483,"quote":"interference in electoral processes dividing the world into zones of influence and neoc colonial incursions for strategic resources are anacronistic gestures.","topic":"Venezuela elections","target":"Neocolonial states"},{"t":508,"quote":"the crisis in Haiti continues to test the limits of the international community's indifference.","topic":"Venezuela elections","target":"International community"},{"t":518,"quote":"collective punishment is imposed on 10 million people by an illegal economic and energy","topic":"Venezuela elections","target":"Cuba"},{"t":661,"quote":"When governments capulate visav those who use tariffs as weapons of coercion and blackmail, consequences are harmful.","topic":"Climate change","target":"Protectionist governments"},{"t":670,"quote":"In the age of misinformation, obscurantists resist the evidence of science.","topic":"Climate change","target":"Obscurantists"},{"t":685,"quote":"Antivaccine campaigns are bringing back diseases we thought were","topic":"Climate change","target":"Anti-vaccine groups"},{"t":691,"quote":"Weakening the World Health Organization makes everyone more vulnerable.","topic":"Climate change","target":"WHO critics"},{"t":869,"quote":"A handsful of technical oligarchs, one to resurrect a version of digital ultra liberalism without rules or They are promoting a race with no ethical boundaries, bypassing the United Nations and the Scientific Panel on Artificial Intelligence.","topic":"AI regulation","target":"Tech oligarchs"},{"t":949,"quote":"multinationals that want to privatize our PIX","topic":"Brazil digital policy","target":"Multinational corporations"},{"t":971,"quote":"reactionary forces that wish to normalize injustices, inequality and underdevelopment","topic":"Brazil digital policy","target":"Reactionary forces"}],"greece":[],"said":[{"topic":"UN reform","said":0.1531,"reported":0.4,"articles":6},{"topic":"Climate change","said":0.1009,"reported":0.0,"articles":0},{"topic":"Brazil hunger","said":0.0552,"reported":0.0,"articles":0},{"topic":"Brazil deforestation","said":0.0523,"reported":0.0,"articles":0},{"topic":"Brazil elections","said":0.0515,"reported":0.3333,"articles":5},{"topic":"International Court of Justice","said":0.0509,"reported":0.0,"articles":0},{"topic":"Global development","said":0.0508,"reported":0.0,"articles":0},{"topic":"Israel-Palestine conflict","said":0.0499,"reported":0.0,"articles":0},{"topic":"Brazil economy","said":0.0498,"reported":0.0,"articles":0},{"topic":"Brazil organized crime","said":0.0498,"reported":0.0667,"articles":1},{"topic":"Latin America diplomacy","said":0.0492,"reported":0.0,"articles":0},{"topic":"Women's rights","said":0.0488,"reported":0.0,"articles":0},{"topic":"Brazil digital policy","said":0.0486,"reported":0.0,"articles":0},{"topic":"Transnational organized crime","said":0.0484,"reported":0.0,"articles":0},{"topic":"AI regulation","said":0.0481,"reported":0.0,"articles":0},{"topic":"Venezuela elections","said":0.0479,"reported":0.0,"articles":0},{"topic":"Brazil democracy","said":0.0449,"reported":0.2,"articles":3}],"pickup":[{"outlet":"Naftemporiki","date":"2026-09-22","title":"Λούλα στη ΓΣ: Είμαστε όλοι όμηροι της αδράνειας του Συμβουλίου Ασφαλείας του ΟΗΕ","url":"https://www.naftemporiki.gr/kosmos/2165238/loyla-sti-gs-eimaste-oloi-omiroi-tis-adraneias-toy-symvoylioy-asfaleias-toy-oie","tone":"neutral"},{"outlet":"In.gr","date":"2026-09-22","title":"Λούλα στον ΟΗΕ: Είμαστε όλοι όμηροι της αδράνειας του Συμβουλίου Ασφαλείας","url":"https://www.in.gr/2026/09/22/world/loula-ston-oie-eimaste-oloi-omiroi-tis-adraneias-tou-symvouliou-asfaleias","tone":"neutral"},{"outlet":"ThePressProject","date":"2026-09-22","title":"Λούλα: «Η αξιοπιστία του ΟΗΕ δεν ήταν ποτέ τόσο χαμηλή – Είμαστε όμηροι της αδράνειάς του»","url":"https://thepressproject.gr/loula-i-axiopistia-tou-oie-den-itan-pote-toso-chamili-eimaste-omiroi-tis-adraneias-tou","tone":"neutral"},{"outlet":"Documento","date":"2026-09-22","title":"Λούλα: Είμαστε όλοι όμηροι της αδράνειας του ΟΗΕ – Προειδοποίησε για ξένη παρέμβαση στις εκλογές της Βραζιλίας","url":"https://www.documentonews.gr/article/loula-eimaste-oloi-omiroi-tis-adraneias-tou-oie-proeidopoiise-gia-xeni-paremvasi-stis-ekloges-tis-vrazilias","tone":"neutral"},{"outlet":"In.gr","date":"2026-09-22","title":"Γιορτή σήμερα 23 Σεπτεμβρίου – Ποιοι γιορτάζουν | Εορτολόγιο","url":"https://www.in.gr/2026/09/23/greece/giorti-simera-23-septemvriou-poioi-giortazoun-eortologio","tone":"neutral"},{"outlet":"Efsyn","date":"2026-09-23","title":"ΟΗΕ: Το υπόγειο παζάρι για το Ιράν και το σταδιακό άνοιγμα του Ορμούζ","url":"https://www.efsyn.gr/kosmos/1472582/oie-to-ypogeio-pazari-gia-to-iran-kai-to-stadiako-anoigma-toy-ormoyz","tone":"neutral"}],"transcript":[{"t":2,"topic":null,"text":"The assembly will now hear an address by his excellency Luis Inasio Lula Da Silva, President of the Federative Republic of Brazil. I request I request protocol to escort his excellency and invite him to address the My compliments to the president of the general assembly, Ambassador Calure Raman from Bangladesh. I greet each of the head states of and government and delegates I address specifically the secretary general of the United Nations in particular. Throughout his two terms in office, Antonio Gutier has been a direct witness to the excesses of the Mr."},{"t":73,"topic":"UN reform","text":"President, this is the 10th time I have opened the general debate of this assembly. Since I first took up to this podium in this is undoubtedly the most critical moment for the United Nations. The feeling that drives me today is one of The UN is failing in one of its most important missions to rid humanity of the scourge of war. Its credibility has never been lower. Its ability to protect the most vulnerable, those who have no army or arsenals, has never been so weak. We are all held hostage by the inaction of the security council for failing to fulfill its role. In 1946, at the first session of this assembly, Brazil warned of the high price that the international community would pay for the right to veto."},{"t":142,"topic":"UN reform","text":"This inherent flaw in the UN charter granted the great powers the luxury of being insensible. To this original sin, a profound leadership crisis is now added. The year of 2025 record, the highest number of armed conflict since the World War II. Trillions of dollars are funding a new arms race. Geopolitical tensions threaten to transform regional conflicts into a conflict of global proportions. Those at the helm of crucial decisions must act with responsibility and with a sense of urgency. The leaders of the country, members of the security council must meet I'm no stranger to the realities of power, but concessions to the law of the stronger have surpassed all limits."},{"t":207,"topic":"Brazil hunger","text":"This is not idealism, but pure realism. War is not the continuation of politics by other means. It's the complete breakdown of politics. In an interdependent world, leading is to reconcile the interest of the nation with those of humanity. This is the observation of someone who represents a nation that loves peace and freedom. Someone who fought against a military dictatorship and defended their country against a coupetar. It is the conviction of a plant worker who was elected president three times and re who removed Brazil from the hunger map. This general assembly recently corrected a historical distortion in the world map. It recognized the trafficking of enslaved Africans as the gravest crime against It approves a more accurate representation of the world map."},{"t":278,"topic":"Israel-Palestine conflict","text":"Now it needs to focus on issues crucial for the future of humanity. We are called to choose between multilateralism or democracy or extremism, sovereignty or These choices require courage, political will and clarity of objectives. This is what we expect from a statesman. Yaser Rafat and Rabin were statesmen. They challenged the past to envision a future of peace. They were defeated by hatred. Generations of Palestinians will carry the pain and trauma left by the genocide of women and children perpetrated by Netanyahu government in Gaza. Israeli civilians paid the price for radicalism and intolerance of Hamas terrorist acts."},{"t":342,"topic":"International Court of Justice","text":"Persecuting the International Criminal Court and its members encourages these crimes to go unpunished. The UN special reporter Francesca Albanese must not be silenced for telling the truth. Illegal settlements in the West Bank are making the two-state solution increasing unviable essential for Israelis and Palestinians to live in Threatening civilizations with extinction will not bring stability to the Middle East. The street of Ormuz became has become a battleground when it should have remained a vital passage for international trade. Families around the world are paying for the rising the price of fuel, fertilizers, and food. The war between Russia and Ukraine has dragged on for five years in a humanitarian drama that continues to claim lives."},{"t":408,"topic":"Latin America diplomacy","text":"We all know that there will be no winners on the battlefield. Diplomacy is the only option. Initiatives such as the friends of peace group created by Brazil and China reveal that there are forces in the international community willing to work towards dialogue. In Latin America and the Caribbean region, geographical pro proximity to the world's greatest military power is inescapable, especially in the context of renewed hegeimmonic temptations. Brazil does not fit in anyone's We need partners with a positive agenda that fosters development. Ideological differences should not hinder higher integration amongst neighbors. The countries in the region have experienced the horrors of authoritarian regimes."},{"t":472,"topic":"Venezuela elections","text":"We have a come a long way to restore popular will. Democracy is once again under threat. We witness once more interference in electoral processes dividing the world into zones of influence and neoc colonial incursions for strategic resources are anacronistic gestures. The Venezuelan people deserve to define their own destiny. Nicaragua will not solve its problems by preventing the opposition from running in the elections. The crisis in Haiti continues to test the limits of the international community's indifference. In Cuba, the world watches in horror as collective punishment is imposed on 10 million people by an illegal economic and energy Mr. President, Brazil does not underestimate the challenge represented by organized crime."},{"t":534,"topic":"Transnational organized crime","text":"We are ready to face the criminal organization that terrorize our local communities. Workers are har are robbed. Mothers lose their children. Police officers do not make it back home. People are tired of violence. But we will not we will not outsource the responsibility of defending its borders and guaranteeing our population the right to live without fear. We do not need aircraft carriers guarding our waters. We need cooperation to block the flow of weapons and money that feeds crime, organized crime. That's the spirited of the proposal that I personally handed to the US president. We want to fight money laundering carried out by Brazilian criminals abroad. For a long time, Brazilian states acted each in their own way. Crime made the most of the lack of coordination. But this is changing."},{"t":597,"topic":"Brazil organized crime","text":"In Manal, the city of the Amazon state, we created the Amazon International Police Cooperation Center, bringing together public safety authorities from nine Amazon region countries. In 2025, we carried out the biggest operation against organized crime in Brazil's history. We broke records of drug seizures as well as unlawful assets and resources. We are facing all levels of crime, including the crime tycoons. The anti-faction bill that we just have passed establish heavier sentences for organized crime than those carried by terrorism. Organized crime and corruption walk hand in hand. The fight against corruption shall remain relentless no matter who it hurts. No one is above the law. Ladies and gentlemen, the pillars of multilateralism are being eroded. The World Trade Organization is being kept on life support."},{"t":661,"topic":"Climate change","text":"When governments capulate visav those who use tariffs as weapons of coercion and blackmail, consequences are harmful. In the age of misinformation, obscurantists resist the evidence of science. We will never forget the millions of lives lost due to the negligence in the fight against COVID 19. Antivaccine campaigns are bringing back diseases we thought were Weakening the World Health Organization makes everyone more vulnerable. Until recently, the response to climate change was firmly established at the center of the international agenda. This year, however, the topic disappeared from the debates of the G7 and G20 forums that bring together the largest carbon emitters. It is time to resume the offensive and inflict a defeat on Nature reminds us every day that we live on one planet."},{"t":730,"topic":"Climate change","text":"The glaciers in the Himalayas are melting. The super aeronneo may cause torrential rains, droughts, and forest fires in different parts of the globe. Its effects will hit the most vulnerable the hardest. Brazil has been demonstrating that it is possible to combine economic growth with reduced emissions. We have achieved our self-sufficiency in oil and will continue to explore the potential of new reserves such as those in the equatorial margin. But we will not abandon the environmental agenda. We will move forward with a road map for the decarbonization of the Brazilian economy. The tropical forest forever facility launched at COPE 30 in the city of Bain shows that it is possible to change old paradigms."},{"t":792,"topic":"Brazil deforestation","text":"The forest is worth more standing than destroyed. We will continue to reduce deforestation which has been cut in half in the Amazon and reaching its lowest level in 11 years. We have the moral authority to reject protectionist measures. disguised as commitment to the environmental cause. Brazil is a global reference in green energy. We have the critical minerals and the rare earths that the world needs to make the energy Our natural wealth belongs to the Brazilian people and it is in their benefit that it will be exploited. Access to our minerals will be contingent upon mandatory value generation in our territory, technology transfer and the supply of strategic national sectors. Mr. President, we are living through unprecedented technological revolution with great risks and opportunities."},{"t":860,"topic":"AI regulation","text":"It would be an unforgivable historical omission not to address the challenge of regulating the big techs and artificial intelligence. A handsful of technical oligarchs, one to resurrect a version of digital ultra liberalism without rules or They are promoting a race with no ethical boundaries, bypassing the United Nations and the Scientific Panel on Artificial Intelligence. As Pope Leo 14th warned, decisions about technology should quote should never be separated from awareness and responsibility. End of quote. Companies that are aware of the risk of their products are transferring the impossible task of confronting algorithm to the families. The billiond dollar bedding industry turns addiction into profit. Its exponential dissemination is increasing debt levels and destroying homes."},{"t":923,"topic":"Brazil digital policy","text":"Brazil will not tolerate this business We passed one of the most advanced pieces of legislations in the world to protect children, adolescents, and women in the digital environment. We will ensure fair compensation for artists, musicians, and other visual content creators. We will not give in to pressure from multinationals that want to privatize our PIX, a free public payment infrastructure that has made financial inclusion a reality for millions of Brazilians. Ladies and gentlemen, the sustainment development goals are currently under attack. Attack from reactionary forces that wish to normalize injustices, inequality and underdevelopment are the result of political choices. It is possible to include the poor in the budget and make the rich pay their share."},{"t":986,"topic":"Global development","text":"It is necessary to cut privileges and invest in free quality education and healthcare. There is a legitimate desire for change throughout the world. But change is not the same as going backwards. It's not about taking away rights. It's not about reviving theories of racial supremacy or female subjugation. It's not about recolonizing the global south. Change means moving towards a more participatory future and more achievements. It is about creating and sharing effective public solutions to development challenge through a democratic, strong, efficient and capable state. It's about betting on the spirit of solidarity and cooperation with Africa, Asia, Latin America, and the Caribbean region. Initiatives such as the global alliance against hunger and poverty launched by Brazil and the UN intergovernmental panel on inequality launched by South Africa steamed from this political will. Brazil is in a hurry to become a developed and socially fair nation."},{"t":1052,"topic":"Brazil economy","text":"We have adopted an economic model based on income distribution, job creation and wage increases. We are invested in improving productivity, expanding credit, and building a robust social safety net. Brazil has returned to sustainable growth. We are the third largest destination of for foreign direct investment. Despite the high tariffs imposed against our economy, this year we shall break a new record in our exports. There's still much to be done. The world of work is undergoing a transformation. Older people want to stay active. Young people want to become entrepreneurs. Workers need time to rest, improve their skills, and spend time with their families in Brazil. Achieving this goal requires ending the so-called six* one working schedule to guarantee workers two days off per week."},{"t":1116,"topic":"Women's rights","text":"This change is crucial to alleviate the domestic burden that still falls on We are building a Brazil where women don't need permission to occupy positions of power or enter the job market. A country free from femicide where no woman inside or outside their home lives under the threat of violence. Where once again, no woman inside or outside their home lives under the threat of violence. This is a cause that the whole world needs to embrace. Mr. President, when he was awarded the Nobel Peace Prize, Dr. Martin Luther King stated, quote, \"What self-centered men have torn down, other centered men can build up.\" End of quote."},{"t":1180,"topic":"UN reform","text":"The UN was born under the sign of hope. Over eight decades, it has contributed to the decolonization, promoted human rights, and supported sustainable development. It has protected migrants and refugees, condemned racism, anti-semitism, and religious intolerance. These were achievements of leaders who took up to this podium driven by indignation at the injustices of their men and women who refuse to accept war as a destiny, colonialism as a right, aparttheide as a legitimate system. It was from this ability to say no to inequalities that some of the greatest transformations we have experienced were born. Faced with the paralysis of the United Nations. We need to rediscover the political will so that it may once again become a tempo of peace."},{"t":1244,"topic":"Brazil elections","text":"I want to conclude with a message from my country to everyone who is listening. On October the 4th, millions of Brazilians will go to the polls to define their destiny. They're not just voting for president of the republic, state governors, and representatives of the legislative branch. They will decide between democracy and deniialism. If Brazil will move towards a future with more opportunities or go back to a past of exclusion, we shall have competitive and transparent elections where every candidate benefits from the broadest freedom of speech. We know that some abuse of this freedom to associated themselves with foreign interests against the country. We do not underestimate the challenge of misinformation networks that aim to distort public debate during the campaign."},{"t":1311,"topic":"Brazil democracy","text":"But we have a modern and robust election system under the watchful eye of a pluralistic citizenry and a free press. We will not allow the enemies of democracy, whether domestic or foreign, to undermine popular will. Brazilian democracy belongs to Brazilians. Brazil continues to be a sovereign country. Nobody, nobody will turn us away from this path. May God bless us all and thank you very much. On behalf of the assembly, I would like I would wish to thank President of the Federative Republic of Brazil."}],"compare":[{"topic":"UN & its reform","share":0.1531,"mean":0.205,"rank":117,"others":170},{"topic":"Climate Change","share":0.1009,"mean":0.0425,"rank":27,"others":77},{"topic":"International Law & Order","share":0.0509,"mean":0.0604,"rank":89,"others":102},{"topic":"Sustainable Development","share":0.0508,"mean":0.0123,"rank":22,"others":28},{"topic":"Israel–Palestine","share":0.0499,"mean":0.0524,"rank":71,"others":76},{"topic":"Latin America","share":0.0492,"mean":0.0044,"rank":11,"others":12},{"topic":"Human Rights","share":0.0488,"mean":0.0084,"rank":18,"others":24},{"topic":"Transnational Crime","share":0.0484,"mean":0.0034,"rank":4,"others":4}]};
